"use strict";
(()=>{const L=window.Lab;if(!L||!L.$('pde-lab'))return;L.init(['time','diffusivity'],()=>{const t=L.range('time'),k=L.range('diffusivity'),rate=k*Math.PI**2,A=Math.exp(-rate*t),g=L.$('drawing');g.replaceChildren();const a=L.svg('g'),b=L.svg('g',{transform:'translate(0,275)'});g.append(a,b);L.plot(a,[{fn:x=>Math.sin(Math.PI*x),color:'#172a45',dash:'6 5'},{fn:x=>A*Math.sin(Math.PI*x)}],{xMax:1,yMin:0,yMax:1.1,height:270,xLabel:'位置 x（m）；此圖固定時間',yLabel:'溫差 u（K）'});const ax=L.plot(b,[{fn:z=>Math.exp(-rate*z),color:'#cf604b'}],{xMax:.5,yMin:0,yMax:1.1,height:270,xLabel:'時間 t（s）；此圖固定 x=0.5 m',yLabel:'中央溫差 u（K）'});b.append(L.svg('circle',{cx:ax.X(t),cy:ax.Y(A),r:5,fill:'#172a45'}));L.text('result-primary',L.fmt(A,6)+' K');L.text('result-secondary',L.fmt(-rate*A)+' K/s');L.text('feedback','在 x=0.5 m、t='+L.fmt(t)+' s，uₜ = −κ(π/L)²u（L=1 m）= '+L.fmt(-rate*A)+' K/s；κuₓₓ 也等於同一值。κ='+L.fmt(k)+' m²/s；κ 越大，衰減率 κ(π/L)² 越大，同一正時間的溫差越小；瞬時下降速度的絕對值未必較大。兩端始終保持溫差 0 K，這是固定溫度邊界，並不是絕熱。上圖橫軸是位置，下圖才是時間。');});})();
